import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def quote(p,t): return {'page':p,'quote':t}
def audit(k,s,f,r,p,q): return dict(standard=k,status=s,facts=f,reason=r,pages=p,quote=q)
def chain(rows,claim,summary,construct,item,dim,ind,result,pages,**kw):
 d=dict(legacy_rows=rows,claim_quote=claim,claim_summary=summary,claim_type='C1',construct_raw=construct,indicator_raw=construct,item_quote=item,dimension_code=dim,indicator_code=ind,instrument_raw='自编7点Likert问卷；Table 2',tool_family_codes=['M1'],tool_origin_code='T3',adaptation='NR',response_scoring='7点Likert；逐题均值、标准差、最小值与最大值；端点文字未报告',validity_evidence='参考Han et al. (2021)构建美观、新颖、功能和可行性维度；未报告预试或效度检验',reliability_evidence='已阅读全文，未报告问卷信度或重复测量证据',result_quote=result,effect_direction='描述性',pages=pages,audit_overrides=[])
 d.update(kw); return d
def save(d):
 p=ROOT/'agents'/f"paper_{d['paper_id']:03}.json"
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
 print(p.name)

